async def execute(minion, kind=""):
    """Run the LXD Borg backup on a host (state.apply lxd_backup.backup)."""
    api = env['saltstack.api']
    kwargs = {}
    if kind:
        kwargs["pillar"] = {"kind": kind}
    return api.salt_call("local", minion, "state.apply", "lxd_backup.backup", **kwargs)

async def execute(minion, artifact, target, archive=""):
    """Extract one LXD artifact from Borg (state.apply lxd_backup.restore)."""
    api = env['saltstack.api']
    pillar = {"artifact": artifact, "target": target}
    if archive:
        pillar["archive"] = archive
    return api.salt_call("local", minion, "state.apply", "lxd_backup.restore",
                         pillar=pillar)

async def execute(customer, snapshot="latest", target="", dry_run=True, minion="restic"):
    """Restore a customer bucket from restic (dry-run by default)."""
    api = env['saltstack.api']
    args = [f"/usr/local/bin/restic-restore.sh", customer, snapshot]
    if target:
        args.append(target)
    if dry_run:
        args.append("--dry-run")
    return api.salt_call("local", minion, "cmd.run", " ".join(args))
